def _build_body():
    return [
        mb_html.heading_level_1(_TITLE),
        *cmn.s_file_naming(),
        *_s_top_level(),
        *s_book39(),
        *s_chapter(),
        *s_verse(),
        *_s_template_objects(),
        *_s_common_templates(),
        *_s_pseudo_verses(),
    ]


